import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        int[][] result = new int[n][n];

        // Directions: R→D→L→U
        int[] xDir = {0, 1, 0, -1};
        int[] yDir = {1, 0, -1, 0};

        // Starting direction is R
        int tmpDir = 0;

        // Start at the center
        int x = (n - 1) / 2;
        int y = (n - 1) / 2;

        // Place Takahashi at the center
        result[x][y] = 0;

        // Current size
        int tmp = 1;
        while (tmp <= n * n - 1) {
            // Check next position
            int nextX = x + xDir[tmpDir];
            int nextY = y + yDir[tmpDir];
            if (nextX >= 0 && nextX < n && nextY >= 0 && nextY < n && result[nextX][nextY] == 0) {
                // Can move to next position without changing direction
            } else {
                // Change direction if can't move
                tmpDir = (tmpDir + 1) % 4;
            }
            x += xDir[tmpDir];
            y += yDir[tmpDir];
            result[x][y] = tmp;
            tmp++;
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == (n - 1) / 2 && j == (n - 1) / 2) {
                    System.out.print("T" + " ");
                } else {
                    System.out.print(result[i][j] + " ");
                }
            }
            System.out.println("");
        }
    }
}
